RANK_ORDER = ["F", "E", "D", "C", "B", "A", "S"]


def can_equip_rune(rune_id: str, champion_rank: str) -> bool:
    rune = RUNE_CATALOG.get(rune_id)
    if not rune:
        return False
    req = rune["rank_req"]
    try:
        return RANK_ORDER.index(champion_rank) >= RANK_ORDER.index(req)
    except ValueError:
        return False
